#include <cmath>
#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

// With no failure in `runs` runs, the highest failure rate still consistent with that at 95%
// confidence. The rule of thumb 3/runs is the approximation of this.
[[nodiscard]] double upper_bound(std::int64_t runs) {
  return 1.0 - std::pow(0.05, 1.0 / static_cast<double>(runs));
}

// The chance that a scenario which really fails one run in twenty passes `runs` runs in a row,
// which is the chance it looks clean while it is not.
[[nodiscard]] double looks_clean(std::int64_t runs, double real_rate) {
  return std::pow(1.0 - real_rate, static_cast<double>(runs));
}

int main() {
  constexpr double real_rate = 0.05;
  std::cout << std::format("{:>6} {:>22} {:>26}\n", "runs", "failure rate under", "a 5% flake passes them all");
  for (const std::int64_t runs : std::vector<std::int64_t>{1, 5, 10, 20, 60, 100}) {
    std::cout << std::format("{:>6} {:>21.1f}% {:>25.1f}%\n", runs, 100.0 * upper_bound(runs),
                             100.0 * looks_clean(runs, real_rate));
  }
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

// One run of a check is a number. Ten runs are a number and a spread, and only the spread says
// whether the limit has any margin left.
struct Spread {
  double lowest;
  double highest;
  std::int64_t outside;
};

[[nodiscard]] Spread spread_of(std::span<const double> values, double at_most) {
  Spread result{.lowest = values.front(), .highest = values.front(), .outside = 0};
  for (const double value : values) {
    result.lowest = std::min(result.lowest, value);
    result.highest = std::max(result.highest, value);
    if (value > at_most) ++result.outside;
  }
  return result;
}

struct Check {
  std::string_view what;
  std::string_view unit;
  double at_most;
  std::vector<double> runs;
};

int main() {
  // Ten runs of the same scenario. Put your own numbers here.
  const std::vector<Check> checks{
      {.what = "time from first movement",
       .unit = "s",
       .at_most = 20.0,
       .runs = {7.66, 7.70, 7.64, 7.72, 7.68, 7.65, 7.71, 7.69, 7.67, 7.73}},
      {.what = "top speed",
       .unit = "m/s",
       .at_most = 0.30,
       .runs = {0.204, 0.207, 0.203, 0.298, 0.205, 0.206, 0.204, 0.208, 0.205, 0.203}},
      {.what = "distance from the last goal",
       .unit = "m",
       .at_most = 0.10,
       .runs = {0.041, 0.038, 0.044, 0.099, 0.040, 0.043, 0.039, 0.101, 0.042, 0.040}},
  };

  std::cout << std::format("{:<28} {:>11} {:>8} {:>8} {:>8} {:>8}\n", "check", "limit", "lowest", "highest",
                           "margin", "outside");
  for (const Check& check : checks) {
    const Spread spread = spread_of(check.runs, check.at_most);
    const double margin = 100.0 * (check.at_most - spread.highest) / check.at_most;
    std::cout << std::format("{:<28} {:>11} {:>8.3f} {:>8.3f} {:>7.1f}% {:>8}\n", check.what,
                             std::format("{:.3f} {}", check.at_most, check.unit), spread.lowest, spread.highest,
                             margin, spread.outside);
  }
}
